onClick:
{{
  (async () => {
    const item = List_KlimaPC.triggeredItem;
    if (!item) return;

    // 1. Sofort lokal über den Data_Helper entfernen (verschwindet ohne Reload)
    const currentData = appsmith.store.lokaleBewaesserungData || Bewaesserung_Lesen.data;
    const rowIdx = await Data_Helper.entferneLokalenEintrag(item, currentData);

    // 2. Im Hintergrund Google Sheets synchronisieren
    if (rowIdx !== undefined) {
      await Bewaesserung_Update_Status.run({
        "realRowIndex": rowIdx
      });
    }
  })()
}}

text:
{{
  (() => {
    const item = typeof currentItem !== 'undefined' ? currentItem : null;
    if (!item) return "";
    if (item.isHeader) return item.titel || "";
    return item.bahn ? "Bahn " + item.bahn + "     •      " + item.Ventil : item.Ventil || "";
  })()
}}
